def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    barrier = next(r for r, row in enumerate(g) if all(v == 2 for v in row))
    obj_rows = [r for r, row in enumerate(g) if any(v not in (2, 4) for v in row)]
    top, bottom = min(obj_rows), max(obj_rows)

    if barrier < top:
        target = top - 1
        if target < 0 or all(v == 2 for v in g[target]):
            target = bottom + 1
    else:
        target = bottom + 1
        if target >= h or all(v == 2 for v in g[target]):
            target = top - 1

    if 0 <= target < h:
        g[target] = [8] * w
    return g
